// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * Rich text: the body of the current page or post (trusted markup from the content source) styled by Prose,
 * under its title and a meta line (date, author, category). Axes: layout (narrow: one reading column; wide: a
 * wider column; sidebar: the body and a side note; media: a cover above the body; card: the body in a card;
 * hero: the title as the page heading over a wide cover), tone, density.
 */
import { type JSX } from "solid-js";
import { Box, Card, Grid, Group, Prose, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { Pill } from "../components/pill";
import { SectionFrame } from "../components/section-frame";
import { htmlOf } from "../utils";
import type { RichEntry, RichMedia, RichMeta, RichAside } from "./rich-text.types";
import type { TrustedHtml } from "../utils";

export type RichTextProps = {
  id: string;
  title?: string;
  content?: TrustedHtml;
  media?: RichMedia;
  meta?: RichMeta;
  aside?: RichAside;
  level?: 1 | 2;
  layout?: "narrow" | "wide" | "sidebar" | "media" | "card" | "hero";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function RichText({
  id,
  title = "",
  content,
  media,
  meta,
  aside,
  level = 2,
  layout = "narrow",
  tone = "default",
  density = "default",
  landmarkLabel,
}: RichTextProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      heading={{ level }}
      tone={tone}
      density={density}
      measure={
        ((layout as string) === "narrow") || ((layout as string) === "media") ? "2xl"
        : (layout as string) === "card" ? "3xl"
        : "default"
      }
      boxed={((layout as string) === "card")}
      landmarkLabel={landmarkLabel}
    >
      {(meta?.date || meta?.author || meta?.category) ? (
        <Group gap="4" align="center" class="flex-wrap" data-testid="richtext-meta">
          {meta?.date ? (
            <Text size="sm" class="text-muted-foreground">
              {meta?.date}
            </Text>
          ) : null}
          {meta?.author ? (
            <Text size="sm" weight="semibold">
              {meta?.author}
            </Text>
          ) : null}
          {meta?.category ? (
            <Pill tone="blue">
              {meta?.category}
            </Pill>
          ) : null}
        </Group>
      ) : null}
      {(((layout as string) === "hero") || ((layout as string) === "media")) ? (
        <MediaFrame
          alt={(media?.alt ?? title)}
          src={media?.src}
          ratio={(((layout as string) === "hero") ? "21/9" : "16/9")}
        />
      ) : null}
      {((layout as string) === "sidebar") ? (
        <Grid cols="1" class="gap-8 lg:grid-cols-3">
          <Box class="min-w-0 lg:col-span-2">
            {content ? (
              <Prose size="base" width="none" data-testid="richtext-content" innerHTML={htmlOf(content)} />
            ) : null}
          </Box>
          {aside?.content ? (
            <Card variant="compact" class="h-fit" data-testid="richtext-aside">
              {aside?.title ? (
                <Title as={((level === 1) ? 2 : 3)} size="lg" weight="semibold">
                  {aside?.title}
                </Title>
              ) : null}
              {aside?.content ? (
                <Prose size="sm" width="none" data-testid="richtext-aside-content" innerHTML={htmlOf(aside?.content)} />
              ) : null}
            </Card>
          ) : null}
        </Grid>
      ) : content ? (
        <Prose
          size="base"
          width={
            (layout as string) === "wide" ? "wide"
            : (layout as string) === "hero" ? "narrow"
            : "none"
          }
          data-testid="richtext-content"
          innerHTML={htmlOf(content)}
        />
      ) : null}
    </SectionFrame>
  );
}

