import type { TrustedHtml } from "../utils";

export type RichEntry = {
  id: string;
  title: string;
  content?: TrustedHtml;
  excerpt?: string;
  date?: string;
  author?: string;
  category?: string;
  image?: string;
  aside?: TrustedHtml;
};

export type RichMedia = {
  /** address of the picture; none: the placeholder */
  src?: string;
  /** accessible name of the picture; none: the title */
  alt?: string;
};

export type RichMeta = {
  /** the date, formatted */
  date?: string;
  /** the author's name */
  author?: string;
  /** the category */
  category?: string;
};

export type RichAside = {
  /** heading of the side note */
  title?: string;
  /** the side note, trusted markup */
  content?: TrustedHtml;
};
